import{z as s,x as d,o as B,c as A,q as n,j as l,D as i,d as e,s as r,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"固定效应与随机效应","description":"","frontmatter":{"title":"固定效应与随机效应","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fe-re.md","filePath":"econ/fe-re.md","lastUpdated":1791063341000}'),_={name:"econ/fe-re.md"};function p(c,E,m,F,u,D){const t=d("Mermaid");return B(),A("div",null,[E[2]||(E[2]=n('<h1 id="固定效应与随机效应" tabindex="-1">固定效应与随机效应 <a class="header-anchor" href="#固定效应与随机效应" aria-label="Permalink to &quot;固定效应与随机效应&quot;">​</a></h1><div class="epigraph"><p>面板里不随时间变的异质 $c_i$ 可以与回归元相关；固定效应把它吸掉，斜率来自组内；随机效应更有效，但要求 $c_i$ 与 $X$ 不相关——这通常正是我们不相信的。</p><footer>—— Mundlak 组内组间；Hausman, Specification Tests in Econometrics, Econometrica 1978；对照 Wooldridge 面板章节</footer></div><p><a href="/econ/mle-bayesian-econ">上一课</a>把似然与后验收成估计原则。本课缺口是：选择来自<strong>看不见、但不随时间变</strong>的 \\(c_i\\)（能力、文化、地理）。固定效应（FE）用组内变异识别；随机效应（RE）把 \\(c_i\\) 当随机、与 \\(X\\) 正交。动态滞后下一课会让 FE 自己产生偏误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(Y_{it}=X_{it}\\beta+c_i+u_{it}\\)。混合 OLS 把组间与组内搅在一起，\\(c_i\\) 与 \\(X\\) 相关则 OVB。一阶差分或去均值（within）消去 \\(c_i\\)，留下 \\(\\beta\\) 对 \\(\\Delta X\\) 或 \\(X_{it}-\\bar X_i\\)。缺口是：时不变的回归元（性别、制度的长期水平）也被消去，不能估；测量误差在组内往往更严重，衰减更重。RE 用 GLS 把组间信息也用上，有效率，可估时不变 \\(X\\)，但要求 \\(\\mathbb{E}[c_i\\mid X_{i1},\\ldots,X_{iT}]=0\\)。Hausman 检验比较 FE 与 RE：拒绝则像是 \\(c_i\\) 与 \\(X\\) 相关，用 FE。不拒绝不是 RE 为真的证明（功效、异方差都会搅）。</p><p><span class="marginnote">Mundlak：把组均值 \\(\\bar X_i\\) 放进相关随机效应，RE 可以复制 FE 的斜率。这是折中：明确组间信息用来估什么。</span></p><p><span class="marginnote">Hausman 检验可以读成「两个估计员对质」：FE 与 RE 都声称估同一个 \\(\\beta\\)，若两者分歧大到抽样误差解释不了，就说明 RE 依赖的「\\(c_i\\) 与 \\(X\\) 无关」站不住。但对质只有功效有限这一场——不拒绝不代表 RE 无罪，可能只是样本太小、检验太钝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>FE：within 回归 + 聚类到 \\(i\\)（或双向聚类）。时间 FE 吸共同冲击。双向 FE 即 TWFE，交错处理时回到两课之前的负权重，不是本课能洗掉的。RE：FGLS。一阶差分在 \\(T=2\\) 与 FE 等价；\\(T\\) 大且 \\(u\\) 有单位根时差分更自然。</p>',9)),(B(),l(o,null,{default:i(()=>[r(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CI%5B%22%E6%9C%AA%E8%A7%82%E6%B5%8B%20c_i%22%5D%20--%3E%20POLS%5B%22%E6%B7%B7%E5%90%88%20OLS%3A%20%E7%BB%84%E9%97%B4%2B%E7%BB%84%E5%86%85%22%5D%0A%20%20CI%20--%3E%20FE%5B%22FE%3A%20%E5%8F%AA%E7%94%A8%E7%BB%84%E5%86%85%22%5D%0A%20%20COR%5B%22c_i%20%E4%B8%8E%20X%20%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20FE%0A%20%20ORTH%5B%22c_i%20%E2%8A%A5%20X%22%5D%20--%3E%20RE%5B%22RE%3A%20%E7%BB%84%E9%97%B4%E4%B9%9F%E7%94%A8%2C%20%E6%9B%B4%E6%9C%89%E6%95%88%22%5D%0A%20%20HAUS%5B%22Hausman%22%5D%20--%3E%20PICK%5B%22%E6%8B%92%E7%BB%9D%E5%88%99%E5%80%BE%E5%90%91%20FE%22%5D%0A"})]),fallback:i(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[e("量化栏的"),a("a",{href:"/quant/panel-fe-finance"},"面板 FE"),e("把同一装置用到公司与资产定价；本课写识别，不重做那些回归，也不进限价簿。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"机制是用单位自己当对照：同一 \\(i\\) 不同 \\(t\\)。CIA 换成「给定 \\(c_i\\) 后时变冲击外生」。严格外生 \\(\\mathbb{E}[u_{it}\\mid X_{i1},\\ldots,X_{iT},c_i]=0\\) 排除反馈（今天的 \\(u\\) 进明天的 \\(X\\)）。一旦有滞后 \\(Y\\)，严格外生失败，Nickell 偏误出现——下一课。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：FE 就是让每个人跟自己比。问「多读一年书是否提高收入」，与其拿博士对比高中生（能力差异搅在一起），不如只看同一个人在读书前后的年份——能力 \\(c_i\\) 两次都在场，一相减就消掉了。RE 则赌能力与读书年限无关，敢把跨人比较也用上。")],-1)),(B(),l(o,null,{default:i(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNIT%5B%22%E5%90%8C%E4%B8%80%E5%8D%95%E4%BD%8D%E4%B8%8D%E5%90%8C%E5%B9%B4%E4%BB%BD%E4%BA%92%E4%B8%BA%E5%AF%B9%E7%85%A7%22%5D%20--%3E%20DEMEAN%5B%22%E5%87%8F%E5%8E%BB%E5%90%84%E8%87%AA%E7%9A%84%E7%BB%84%E5%9D%87%E5%80%BC%22%5D%0A%20%20DEMEAN%20--%3E%20KILL%5B%22c_i%20%E4%B8%8D%E9%9A%8F%E6%97%B6%E9%97%B4%E5%8F%98%20%E8%A2%AB%E5%87%8F%E6%8E%89%22%5D%0A%20%20DEMEAN%20--%3E%20KEEP%5B%22%E5%89%A9%E4%B8%8B%E7%9A%84%E7%BB%84%E5%86%85%E5%8F%98%E5%8C%96%E8%AF%86%E5%88%AB%20beta%22%5D%0A%20%20TINV%5B%22%E6%80%A7%E5%88%AB%20%E5%88%B6%E5%BA%A6%E9%95%BF%E6%9C%9F%E6%B0%B4%E5%B9%B3%20%E4%B8%8D%E9%9A%8F%E6%97%B6%E9%97%B4%E5%8F%98%22%5D%20--%3E%20GONE%5B%22%E4%B9%9F%E8%A2%AB%E4%B8%80%E5%B9%B6%E5%87%8F%E6%8E%89%20FE%20%E4%BC%B0%E4%B8%8D%E5%87%BA%22%5D%0A%20%20NOISE%5B%22%E6%B5%8B%E9%87%8F%E8%AF%AF%E5%B7%AE%E4%B8%8D%E8%B5%B0%E8%BF%90%20%E8%90%BD%E5%9C%A8%E7%BB%84%E5%86%85%22%5D%20--%3E%20WORSE%5B%22%E4%BF%A1%E5%8F%B7%E6%9B%B4%E7%A8%80%20%E8%A1%B0%E5%87%8F%E6%9B%B4%E9%87%8D%22%5D%0A"})]),fallback:i(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=n('<p>组内变异小，则 FE 方差大，且测量误差主导。经验上「加了 FE 系数消失」可能是真的 \\(c_i\\) 混淆，也可能是信号被洗掉。要报告组内 \\(R^2\\) 与 \\(X\\) 的组内标准差。</p><p><span class="marginnote">数字实例：想估「行业经历对工资的影响」，某人十年间行业编码出过一次笔误（制造业记成矿业）。混合回归里这一笔只是漫长样本中的小噪音；FE 只用他与自己十年均值的变化，一笔错值能占他全部组内变异的一大半——系数反而被拉得更歪。FE 不是免费的：它扔掉组间信息的同时，也放大了组内噪音。</span></p><p><span class="marginnote">相关随机效应（Mundlak–Chamberlain）把 \\(\\mathbb{E}[c_i\\mid X_i]\\) 参数化成分组均值，避免「RE 或 FE」的宗教选择，改成声明组间通道。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Hausman 的 \\(p\\) 值写成模型选择的唯一标准。不处理异质 \\(\\beta_i\\)（那是随机系数，后课异质效应）。交错 DiD 的 TWFE 病不是「再加一个 RE」能好的。下一课动态面板：滞后因变量 + FE。</p><p>后课默认：与 \\(c_i\\) 相关的时变 \\(X\\) 用 FE；时不变 \\(X\\) 的效应 FE 估不出。RE 的正交要求必须单独辩护。动态滞后不要默默用 FE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FE 消去时不变 \\(c_i\\)，识别来自组内；时不变 \\(X\\) 一起消失。</li><li>RE 更有效，但要 \\(c_i\\) 与 \\(X\\) 不相关。</li><li>Hausman 是比较，不是证明；Mundlak 把组间写进方程。</li><li>严格外生排除反馈；滞后 \\(Y\\) 下一课。</li><li>出处：Hausman, <em>Econometrica</em> 1978；Mundlak；Wooldridge 面板。</li></ul>',8))])}const b=s(_,[["render",p]]);export{h as __pageData,b as default};
